#include "bt_scheduler.h"
#include <string.h>
void bt_scheduler_init(bt_scheduler *s,void *event_ctx,bt_scheduler_event_fn event_fn){memset(s,0,sizeof(*s));s->event_ctx=event_ctx;s->event_fn=event_fn;}
bool bt_scheduler_add_ticker(bt_scheduler *s,void *ctx,bt_scheduler_tick_fn fn){if(!s||!fn||s->failed||s->ticker_count>=BT_SCHEDULER_MAX_TICKERS){if(s)s->failed=1;return false;}s->tickers[s->ticker_count].ctx=ctx;s->tickers[s->ticker_count].fn=fn;s->ticker_count++;return true;}
bool bt_scheduler_schedule(bt_scheduler *s,uint64_t cycle,uint16_t priority,uint32_t type,uint64_t value){size_t i;if(!s||s->failed||cycle<s->cycle){if(s)s->failed=1;return false;}for(i=0;i<BT_SCHEDULER_MAX_EVENTS;i++)if(!s->events[i].active){s->events[i].cycle=cycle;s->events[i].priority=priority;s->events[i].type=type;s->events[i].value=value;s->events[i].sequence=s->next_sequence++;s->events[i].active=1;return true;}s->failed=1;return false;}
static int earlier(const bt_scheduler_event *a,const bt_scheduler_event *b){if(a->cycle!=b->cycle)return a->cycle<b->cycle;if(a->priority!=b->priority)return a->priority<b->priority;return a->sequence<b->sequence;}
static int next_due(bt_scheduler *s,uint64_t cycle){size_t i;int best=-1;for(i=0;i<BT_SCHEDULER_MAX_EVENTS;i++){if(!s->events[i].active||s->events[i].cycle!=cycle)continue;if(best<0||earlier(&s->events[i],&s->events[(size_t)best]))best=(int)i;}return best;}
bool bt_scheduler_advance_to(bt_scheduler *s,uint64_t cycle){uint64_t c;if(!s||s->failed||cycle<s->cycle){if(s)s->failed=1;return false;}if(cycle==s->cycle){int idx;while((idx=next_due(s,cycle))>=0){bt_scheduler_event e=s->events[(size_t)idx];s->events[(size_t)idx].active=0;if(s->event_fn)s->event_fn(s->event_ctx,e.cycle,e.type,e.value);}return !s->failed;}for(c=s->cycle+1;c<=cycle;c++){size_t i;int idx;s->cycle=c;while((idx=next_due(s,c))>=0){bt_scheduler_event e=s->events[(size_t)idx];s->events[(size_t)idx].active=0;if(s->event_fn)s->event_fn(s->event_ctx,e.cycle,e.type,e.value);if(s->failed)return false;}for(i=0;i<s->ticker_count;i++){s->tickers[i].fn(s->tickers[i].ctx,c);if(s->failed)return false;}if(c==UINT64_MAX)break;}return !s->failed;}
